        from decimal import Decimal
        sound = Rule.objects.create(name=f'{prefix}: Ohne Tontechnik', effect_type='flat_add',
            effect_value=-Decimal(terms['without_sound_discount']), sort_order=1,
            condition_json=[{'field': 'with_sound', 'op': 'eq', 'value': False}])
        formula = Formula.objects.create(name=f'{prefix}: Zusatzstunden und Anfahrt', mode='add',
            expression=f"max(0, ceil((duration_minutes - {terms['included_minutes']}) / 60)) * {terms['extra_hour_rate']} + max(0, 2 * distance - {terms['included_round_trip_km']}) * {terms['km_rate']}")
        workflow = Workflow.objects.create(name=f'{prefix}: Buchung', workflow_json=[
            {'type': 'package'}, {'type': 'items'},
            {'type': 'rules', 'config': {'rule_ids': [guest.pk, sound.pk]}},
            {'type': 'formula', 'config': {'formula_id': formula.pk}},
        ])
        package.workflow = workflow
        package.save(update_fields=['workflow'])
        # Included items are presentation and catalog components, not added charges.
        if package.name == 'Basis-Paket':
            for name in ('DJ-Leistung', 'Lichttechnik', 'Mikrofone'):
                item = Item.objects.create(name=f'{prefix}: {name}', price='0', category='base',
                    is_public=True, is_active=True)
                package.included_items.add(item)


